// A bank account, the obvious way: one object with a `balance` field,
// and functions that add to it and take away from it. Money in cents.

const account = { owner: "Ada", balance: 0 };

function deposit(amount) {
  account.balance += amount;
  // No validation. deposit(-5000) is a withdrawal wearing a disguise,
  // and it skips every rule below.
}

function withdraw(amount) {
  if (amount > account.balance) {
    console.log("declined: insufficient funds");
    return; // returns undefined either way — callers can't tell
  }        // success from failure without re-reading account.balance
  account.balance -= amount;
}

function chargeFee(amount) {
  account.balance -= amount; // no overdraft rule here. Nobody decided
}                            // that; the rule just wasn't copied over.

// Added six months later, by someone in a hurry, in another file:
function payBill(name, amount) {
  account.balance -= amount; // ...and here it wasn't copied either
}

// ---- one month of activity ----------------------------------------
deposit(50000);          // paycheck
withdraw(1250);          // coffee
payBill("rent", 32000);
chargeFee(3500);         // monthly fee
chargeFee(3500);         // the retry that ran twice — THE BUG
deposit(2000);           // refund
payBill("car", 18000);

console.log("balance:", account.balance); // -6250

// ---- now answer these questions ------------------------------------
// Support calls: "my balance is negative, and your app says that's
// impossible. What happened?"
//
//   1. When did the balance first go negative?          -> unknown
//   2. Was the monthly fee really charged twice?        -> unknown
//   3. What was the balance last Tuesday?               -> unknown
//   4. Which code path skipped the overdraft check?     -> unknown
//   5. Can we undo just the duplicate fee?              -> no
//
// Every answer is "unknown" for the same reason: `balance += amount`
// OVERWRITES. Each change destroys the only evidence of the change
// before it, and the object we print at the end is the single
// surviving frame of a film nobody recorded.
console.log(account); // { owner: 'Ada', balance: -6250 }

// You could sprinkle console.log into every function... which is a
// log. Project 83's question: what if the log WERE the account, and
// the balance were just something we compute from it?

# 🏋️ Practice: Event-Sourcing Bank

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

Work in `refactored/ledger.js` and `refactored/projections.js`; add your checks to the matching `.test.js` files and run them with `node --test 83-event-sourcing-bank/refactored/ledger.test.js`.

## Exercises

### ⭐ 1. totals() — a new projection in five lines (warm-up)

Write `totals(events)` returning `{ depositedCents, withdrawnCents, feesCents }`. Then assert the invariant that ties it to everything else: `deposited - withdrawn - fees === balanceCents(events)`.

What it practices: how cheap a new report is once the facts are kept. Notice what you did *not* have to do — no new field to maintain, no migration, no risk to the write side.

Hint: one loop, three `if`s. Start all three sums at `0` so an empty log answers `{0,0,0}` instead of `undefined`.

Check (in node): for the March log, `{ depositedCents: 50000, withdrawnCents: 1250, feesCents: 7000 }`, and the invariant holds exactly.

### ⭐⭐ 2. A new fact: interest-accrued (core)

Add an `accrue-interest` command producing an `interest-accrued` event that increases the balance. Touch `COMMAND_TO_EVENT`, `applyEvent` and `deltaOf` — and nothing else. Confirm that old logs still replay unchanged, that the positive-integer amount rule applies for free, and that `statement` shows the new row correctly.

What it practices: extending a system whose truth is a list of facts. The measure of the design is how *few* places you have to touch.

Hint: `deltaOf` and `applyEvent` are the two places that decide what an event *means*; validation is generic already, because the amount rules don't care which kind of movement it is.

Check (in node): appending `{ type: 'accrue-interest', amountCents: 125, at: '2024-03-31T23:59:00Z' }` yields an `interest-accrued` event, raises the balance by 125, `deltaOf` returns `+125`, and a negative amount is still `INVALID_AMOUNT`.

### ⭐⭐ 3. Snapshots (core)

Replaying a million events to show a balance is silly. Write `takeSnapshot(events)` → `{ eventIndex, at, state }` and `replayFrom(snapshot, events)` which folds only the events *after* the snapshot. The rule that keeps this honest: a snapshot is a **cache**, never a second source of truth — deleting it must lose nothing.

What it practices: making a derived value fast without promoting it to the truth. This is the same bargain as project 27's memoize: cached answers, recomputable at will.

Hint: `events.slice(snapshot.eventIndex).reduce(applyEvent, snapshot.state)`. Test it with a snapshot at 0, in the middle, and at the very end.

Check (in node): `replayFrom(takeSnapshot(events.slice(0, 3)), events)` deep-equals `replay(events)`, and still does after more events are appended.

### ⭐⭐ 4. Undo by appending the opposite (core)

The customer wants the duplicate fee refunded. You cannot delete event #4 — it happened. Add a `reverse` command taking `targetIndex`, appending `{ type: 'reversed', targetIndex, deltaCents }` whose delta is the *opposite* of the target's. Refuse: an index that doesn't exist, an event that moved no money, an event already reversed, and a reversal that would push the balance negative.

What it practices: the append-only mindset. History gets *longer*, never shorter — so the refund itself is auditable, which is precisely what a bank needs.

Hint: this rule needs the log, not just the state (has this event been reversed before?), so validate it in `append`, where the log is in scope, via a helper `validateReversal(events, state, command)`.

Check (in node): reversing the duplicate fee grows the log by one, leaves the first five events byte-identical, raises the balance by 3500, and a second reversal of the same index returns `ALREADY_REVERSED`.

### ⭐⭐⭐ 5. A store around the log (challenge)

Wrap the log the way project 59 wrapped state: `createStore(initialEvents)` with `dispatch(command)` (returns the Result), `getState()`, `getEvents()` and `subscribe(listener)` returning an unsubscribe function. Two requirements: the cached state must be updated **incrementally** (`applyEvent`, not a full `replay`) and must always equal `replay(getEvents())`; and a *rejected* command must notify nobody.

What it practices: joining project 59's one-door-in idea to an event log — which is what Redux's devtools, with their time-travel slider, actually are.

Hint: `getEvents()` must return a copy (`[...events]`), or a caller can push straight into your history and skip every rule.

Check (in node): after two accepted and one rejected dispatch, listeners saw exactly two notifications, `getEvents().length` is 2, `getState()` deep-equals `replay(getEvents())`, and pushing onto the array returned by `getEvents()` doesn't change the store.

### ⭐⭐⭐ 6. Fuzz the promises (challenge)

Write a fuzz test: 300 trials of 40 random commands (random types, random amounts, sometimes illegal, increasing timestamps), asserting after *every* command that the balance is never negative, the log grew by at most 1, a rejection appended nothing, `eventCount === events.length`, the deltas sum to the balance, the statement's last row matches the balance, and the store's cached state equals a full replay.

What it practices: property-based testing against invariants. The original could not satisfy a single one of these properties, and no example test would have found the `payBill` hole — but a fuzzer finds it in milliseconds.

Hint: bias the generator so ~15% of amounts are illegal (zero or negative); otherwise you only ever test the happy path.

Check (in node): 300 × 40 operations pass. Then delete the `MONEY_OUT` check from `validate` and watch "balance went negative in trial N" fire almost immediately.

## Solutions

### 1. totals()

```js
export function totals(events) {
  const sums = { depositedCents: 0, withdrawnCents: 0, feesCents: 0 };
  for (const event of events) {
    if (event.type === 'deposited') sums.depositedCents += event.amountCents;
    if (event.type === 'withdrew') sums.withdrawnCents += event.amountCents;
    if (event.type === 'fee-charged') sums.feesCents += event.amountCents;
  }
  return sums;
}
```

WHY: the interesting part is the assertion, not the function. `deposited - withdrawn - fees === balance` is a **cross-check**: two independent walks over the same facts that must agree. In the original there was nothing to cross-check *against* — one number, take it or leave it. Note also what this exercise did not require: no schema change, no backfill, no coordination with whoever writes events. New questions are cheap when the answers aren't stored. Verified by running: `{50000, 1250, 7000}` and the invariant holds.

### 2. interest-accrued

```js
const COMMAND_TO_EVENT = {
  open: 'opened', deposit: 'deposited', withdraw: 'withdrew',
  'charge-fee': 'fee-charged',
  'accrue-interest': 'interest-accrued',   // <- new
};

// applyEvent:
case 'interest-accrued':
  return { ...base, balanceCents: state.balanceCents + event.amountCents };

// deltaOf:
if (event.type === 'deposited' || event.type === 'interest-accrued') return event.amountCents;
```

WHY: three lines, in the three places that define what an event *means* — and zero lines in validation, because "a positive whole number of cents" was never a fact about deposits specifically. Old logs replay identically because nothing about them changed; that's the backward compatibility you get from append-only data. The one thing to be careful about is naming: `interest-accrued`, past tense, because by the time it's in the log it has happened. If you find yourself wanting to *edit* an old event to add interest, that's the instinct this project exists to retrain. Verified by running: balance +125, `deltaOf` +125, statement row correct, negative amount still `INVALID_AMOUNT`.

### 3. Snapshots

```js
export function takeSnapshot(events) {
  return { eventIndex: events.length, at: events.at(-1)?.at ?? null, state: replay(events) };
}

export function replayFrom(snapshot, events) {
  return events.slice(snapshot.eventIndex).reduce(applyEvent, snapshot.state);
}
```

WHY: `eventIndex` is what makes this safe — it says *exactly* how much of the log the snapshot already accounts for, so `replayFrom` can never double-count or skip. Storing the count rather than a timestamp matters, because two events can share a timestamp (the duplicate fee did). And because `applyEvent` returns new states rather than mutating, the snapshot's `state` can't be corrupted by later folding. Delete every snapshot you have and the system still works, just slower — that's the definition of a cache, and the line real event-sourced systems must not cross. Verified by running: snapshots at 0, 3, and the end all reproduce `replay(events)` exactly, before and after appending more.

### 4. Undo by appending the opposite

```js
export function validateReversal(events, state, command) {
  const target = events[command.targetIndex];
  if (!Number.isInteger(command.targetIndex) || target === undefined) {
    return fail('NO_SUCH_EVENT', `No event at index ${command.targetIndex}`);
  }
  if (deltaOf(target) === 0) {
    return fail('NOT_REVERSIBLE', `A ${target.type} event moved no money`);
  }
  if (events.some((e) => e.type === 'reversed' && e.targetIndex === command.targetIndex)) {
    return fail('ALREADY_REVERSED', `Event #${command.targetIndex} was already reversed`);
  }
  const deltaCents = -deltaOf(target);
  if (state.balanceCents + deltaCents < 0) {
    return fail('INSUFFICIENT_FUNDS', `Reversing would leave ${state.balanceCents + deltaCents}`);
  }
  return { ok: true, deltaCents };
}

// in append(), after the generic validate() passes:
if (command.type === 'reverse') {
  const reversal = validateReversal(events, state, command);
  if (!reversal.ok) return reversal;
  const undo = { type: 'reversed', at: command.at,
                 targetIndex: command.targetIndex, deltaCents: reversal.deltaCents };
  return { ok: true, events: [...events, undo] };
}

// applyEvent:  case 'reversed': return { ...base, balanceCents: state.balanceCents + event.deltaCents };
// deltaOf:     if (event.type === 'reversed') return event.deltaCents;
```

WHY: the reversal event carries its own `deltaCents` rather than making readers look up the target, which keeps `applyEvent` a pure function of one event and one state — the property that lets snapshots and incremental stores work at all. `ALREADY_REVERSED` is the rule that stops a retried refund from paying out twice (the same class of bug as the duplicate fee it's cleaning up, which is not a coincidence). And note where this rule had to live: `validate` only sees the *state*, but "has this been reversed?" is a question about the *log*, so it belongs in `append`. Real ledgers work exactly this way — you'll see the compensating entry on your bank statement next to the mistake, because deleting the mistake would be fraud. Verified by running: log grows by one, first five events byte-identical, balance +3500, and all four refusals fire.

### 5. A store around the log

```js
export function createStore(initialEvents = []) {
  let events = [...initialEvents];
  let state = replay(events);
  const listeners = new Set();
  return {
    getState: () => state,
    getEvents: () => [...events],                     // a copy: nobody edits history
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
    dispatch(command) {
      const result = append(events, command);
      if (!result.ok) return result;                  // refusals notify nobody
      events = result.events;
      const event = events.at(-1);
      state = applyEvent(state, event);               // O(1), not a full replay
      for (const listener of listeners) listener(state, event);
      return { ok: true, event };
    },
  };
}
```

WHY: `state = applyEvent(state, event)` is the whole optimisation — the log is the truth, but you don't re-read it from the beginning every time, exactly as project 59's reducer folds one action into the current state. The fuzz test then pins the two views together (`getState()` must always deep-equal `replay(getEvents())`), which is the assertion that catches the classic incremental-cache bug where the fast path and the slow path drift apart. Returning a copy from `getEvents()` is not paranoia: hand out the real array and one `push` bypasses every rule in the file, which is the original's disease all over again. Verified by running: two notifications for two accepted commands, none for the rejected one, cached state matches replay, and the handed-out array is a copy.

### 6. Fuzz the promises

```js
test('FUZZ: the promises hold for any sequence of commands', () => {
  const TYPES = ['deposit', 'withdraw', 'charge-fee', 'accrue-interest', 'open'];
  for (let trial = 0; trial < 300; trial++) {
    const store = createStore();
    let events = [];
    let clock = Date.parse('2024-03-01T00:00:00Z');

    for (let i = 0; i < 40; i++) {
      clock += Math.floor(Math.random() * 100000);
      const command = {
        type: TYPES[Math.floor(Math.random() * TYPES.length)],
        owner: 'Ada',
        amountCents: Math.random() < 0.15
          ? Math.floor(Math.random() * 2000) - 1000    // sometimes illegal
          : Math.floor(Math.random() * 20000) + 1,
        at: new Date(clock).toISOString(),
      };
      const before = events;
      const result = append(before, command);
      assert.equal(result.ok, store.dispatch(command).ok, 'store and append agree');
      if (result.ok) events = result.events;

      assert.ok(events.length - before.length <= 1, 'at most one event per command');
      if (!result.ok) assert.equal(events, before, 'a refusal appends nothing');

      const state = replay(events);
      assert.ok(state.balanceCents >= 0, `balance went negative in trial ${trial}`);
      assert.equal(state.eventCount, events.length);
      assert.equal(
        events.reduce((sum, event) => sum + deltaOf(event), 0),
        state.balanceCents, 'the deltas always add up to the balance',
      );
      const rows = statement(events);
      assert.equal(rows.length, events.length);
      if (rows.length > 0) assert.equal(rows.at(-1).balanceCents, state.balanceCents);
      assert.deepEqual(store.getState(), state, 'cached state == full replay');
    }
  }
});
```

WHY: read the assertions as sentences and you have the system's contract — *the balance is never negative; a refusal changes nothing; the parts sum to the whole; every view agrees*. The original violated the first and the last within seven lines of its demo, and no amount of careful example-writing would have caught the `payBill` hole, because the person who forgot the rule is the same person who would have written the test. A fuzzer doesn't share your blind spots. The `store and append agree` line is quietly the most valuable one: two implementations of the same idea (recompute vs. cache) checked against each other 12,000 times per run. Verified by running: 300 trials × 40 commands pass; deleting the `MONEY_OUT` overdraft check makes it fail almost immediately.

import { appendAll, replay } from './ledger.js';
import {
  balanceAt, balanceCents, duplicateSuspects, firstBalanceBelow, largestDay, statement,
} from './projections.js';

// The I/O layer: it asks the log questions and prints the answers.
// Every answer below is one function call, and the original could not
// produce a single one of them.

const money = (cents) => `${cents < 0 ? '-' : ''}$${(Math.abs(cents) / 100).toFixed(2)}`;

// ---- 1. the same month as original.js, through the rulebook --------
const { events, rejected } = appendAll([], [
  { type: 'open', owner: 'Ada', at: '2024-03-01T08:00:00Z' },
  { type: 'deposit', amountCents: 50000, at: '2024-03-01T09:00:00Z', note: 'paycheck' },
  { type: 'withdraw', amountCents: 1250, at: '2024-03-02T08:15:00Z', note: 'coffee' },
  { type: 'withdraw', amountCents: 32000, at: '2024-03-03T10:00:00Z', note: 'rent' },
  { type: 'charge-fee', amountCents: 3500, at: '2024-03-04T00:00:00Z', note: 'monthly fee' },
  { type: 'charge-fee', amountCents: 3500, at: '2024-03-04T00:00:00Z', note: 'monthly fee (retry)' },
  { type: 'deposit', amountCents: 2000, at: '2024-03-05T12:00:00Z', note: 'refund' },

  // Four commands the original happily performed:
  { type: 'deposit', amountCents: -5000, at: '2024-03-05T13:00:00Z' },
  { type: 'withdraw', amountCents: 18000, at: '2024-03-06T09:00:00Z', note: 'car' },
  { type: 'open', owner: 'Bob', at: '2024-03-06T10:00:00Z' },
  { type: 'deposit', amountCents: 100, at: '2024-01-01T00:00:00Z', note: 'backdated' },
]);

console.log('=== rejected commands (the log never grew) ===');
for (const { command, error } of rejected) {
  console.log(`  ${command.type.padEnd(11)} ${error.code.padEnd(19)} ${error.message}`);
}
console.log(`  log length: ${events.length} events for ${7 + rejected.length} commands`);

// ---- 2. state is derived, never stored -----------------------------
const state = replay(events);
console.log(`\n=== ${state.owner}: ${money(state.balanceCents)} after ${state.eventCount} events ===`);
for (const row of statement(events)) {
  const delta = row.deltaCents === 0 ? '' : money(row.deltaCents);
  console.log(
    `  ${row.at}  ${row.type.padEnd(12)} ${delta.padStart(9)}  ` +
    `-> ${money(row.balanceCents).padStart(9)}  ${row.note ?? ''}`,
  );
}

// ---- 3. time travel ------------------------------------------------
console.log('\n=== "what was the balance on...?" ===');
for (const when of ['2024-03-01T00:00:00Z', '2024-03-02T23:59:59Z', '2024-03-04T23:59:59Z']) {
  console.log(`  ${when}  ${money(balanceAt(events, when))}`);
}
const busiest = largestDay(events);
console.log(`  busiest day: ${busiest.day} (${money(busiest.netCents)} over ${busiest.eventCount} events)`);
console.log(`  ever below zero? ${firstBalanceBelow(events, 0) === null ? 'no — and that is now provable' : 'yes'}`);

// ---- 4. the bug hunt -----------------------------------------------
// A log exported from the OLD system: the same story, but the fee ran
// twice and the car payment skipped the overdraft check. `append`
// would have refused the last one; these events are pasted in raw,
// exactly as the legacy code wrote them.
const legacyLog = [
  { type: 'opened', owner: 'Ada', at: '2024-03-01T08:00:00Z' },
  { type: 'deposited', amountCents: 50000, at: '2024-03-01T09:00:00Z', note: 'paycheck' },
  { type: 'withdrew', amountCents: 1250, at: '2024-03-02T08:15:00Z', note: 'coffee' },
  { type: 'withdrew', amountCents: 32000, at: '2024-03-03T10:00:00Z', note: 'rent' },
  { type: 'fee-charged', amountCents: 3500, at: '2024-03-04T00:00:00Z', note: 'monthly fee' },
  { type: 'fee-charged', amountCents: 3500, at: '2024-03-04T00:00:02Z', note: 'monthly fee' },
  { type: 'deposited', amountCents: 2000, at: '2024-03-05T12:00:00Z', note: 'refund' },
  { type: 'withdrew', amountCents: 18000, at: '2024-03-06T09:00:00Z', note: 'car' },
];

console.log(`\n=== support ticket: "my balance is ${money(balanceCents(legacyLog))}. What happened?" ===`);
const wentNegative = firstBalanceBelow(legacyLog, 0);
console.log(
  `  went negative at event #${wentNegative.index}: ` +
  `${wentNegative.type} ${money(-wentNegative.deltaCents)} (${wentNegative.note}) ` +
  `on ${wentNegative.at}, leaving ${money(wentNegative.balanceCents)}`,
);
console.log(`  balance the moment before: ${money(balanceAt(legacyLog, '2024-03-06T08:59:59Z'))}`);
for (const suspect of duplicateSuspects(legacyLog)) {
  console.log(
    `  duplicate suspect: events #${suspect.firstIndex} and #${suspect.repeatIndex} — ` +
    `${suspect.event.type} ${money(suspect.event.amountCents)} twice on ${suspect.key.slice(0, 10)}`,
  );
}
console.log(`  balance without the duplicate fee: ${money(
  balanceCents(legacyLog.filter((_, i) => i !== 5)),
)}`);

// Five questions, five one-liners, zero guesswork — because nothing
// was ever overwritten.

/**
 * EVENT SOURCING: the account is not a balance. The account is the
 * list of things that happened to it, and the balance is something we
 * COMPUTE from that list, on demand.
 *
 *   events (facts, append-only)  ->  replay()  ->  state (derived)
 *
 * An event is plain, past-tense, immutable data:
 *
 *   { type: 'deposited', amountCents: 50000, at: '2024-03-01T09:00:00Z' }
 *
 * Nothing here ever overwrites anything, so no evidence is ever
 * destroyed: "what was the balance last Tuesday?" is replaying a
 * prefix of the list. This is project 39's undo idea taken to its
 * conclusion, and project 59's "every change is an action you can log"
 * with the log promoted to the source of truth.
 *
 * COMMANDS ("please deposit £5") are requests and can be rejected.
 * EVENTS ("deposited") are facts and can never be rejected, because
 * they already happened. Validation lives on the border between them.
 */

/** A state is a fold of the event list; here is its starting value. */
export function emptyState() {
  return {
    open: false,
    owner: null,
    balanceCents: 0,
    eventCount: 0,
    openedAt: null,
    lastEventAt: null,
  };
}

/**
 * ONE place where an event changes state — used by replay AND by every
 * projection, so no two readers of the log can ever disagree about
 * what an event means. Returns a NEW state; never mutates.
 */
export function applyEvent(state, event) {
  const base = { ...state, eventCount: state.eventCount + 1, lastEventAt: event.at };
  switch (event.type) {
    case 'opened':
      return { ...base, open: true, owner: event.owner, openedAt: event.at };
    case 'deposited':
      return { ...base, balanceCents: state.balanceCents + event.amountCents };
    case 'withdrew':
    case 'fee-charged':
      return { ...base, balanceCents: state.balanceCents - event.amountCents };
    default:
      // The log is the truth, so junk in the log is a crash, not a shrug.
      throw new TypeError(`Unknown event type: ${JSON.stringify(event.type)}`);
  }
}

/** The whole read model in one line: fold the facts into a state. */
export function replay(events) {
  return events.reduce(applyEvent, emptyState());
}

/** How much this event moved the balance (+ in, - out, 0 for opened). */
export function deltaOf(event) {
  if (event.type === 'deposited') return event.amountCents;
  if (event.type === 'withdrew' || event.type === 'fee-charged') return -event.amountCents;
  return 0;
}

const COMMAND_TO_EVENT = {
  open: 'opened',
  deposit: 'deposited',
  withdraw: 'withdrew',
  'charge-fee': 'fee-charged',
};

const MONEY_OUT = new Set(['withdraw', 'charge-fee']);

const ok = () => ({ ok: true });
const fail = (code, message) => ({ ok: false, error: { code, message } });

/**
 * The rulebook — Result-style (project 30): a rejection is a returned
 * value, not a thrown exception, because "you can't afford that" is an
 * expected outcome, not a programming mistake.
 *
 * Note that the overdraft rule is written ONCE and therefore applies to
 * fees as well as withdrawals. In the original, `chargeFee` and
 * `payBill` each forgot to copy it.
 */
export function validate(state, command) {
  if (!COMMAND_TO_EVENT[command?.type]) {
    return fail('UNKNOWN_COMMAND', `No such command: ${JSON.stringify(command?.type)}`);
  }
  if (typeof command.at !== 'string' || Number.isNaN(Date.parse(command.at))) {
    return fail('INVALID_TIMESTAMP', `at must be an ISO date string, got ${command.at}`);
  }
  if (state.lastEventAt !== null && Date.parse(command.at) < Date.parse(state.lastEventAt)) {
    return fail(
      'OUT_OF_ORDER',
      `${command.at} is before the last event at ${state.lastEventAt}`,
    );
  }

  if (command.type === 'open') {
    if (state.open) return fail('ALREADY_OPEN', `Account is already open for ${state.owner}`);
    if (typeof command.owner !== 'string' || command.owner.trim() === '') {
      return fail('INVALID_OWNER', 'owner must be a non-empty string');
    }
    return ok();
  }

  if (!state.open) return fail('NOT_OPEN', 'The account has not been opened yet');
  if (!Number.isInteger(command.amountCents) || command.amountCents <= 0) {
    return fail(
      'INVALID_AMOUNT',
      `amountCents must be a positive whole number of cents, got ${command.amountCents}`,
    );
  }
  if (MONEY_OUT.has(command.type) && command.amountCents > state.balanceCents) {
    return fail(
      'INSUFFICIENT_FUNDS',
      `Cannot take ${command.amountCents} from a balance of ${state.balanceCents}`,
    );
  }
  return ok();
}

/**
 * The only way to grow the log. Returns either a NEW array with one
 * more event, or an error — and on rejection the log is untouched,
 * which is why "how did we get into this state?" always has an answer.
 */
export function append(events, command) {
  if (!Array.isArray(events)) throw new TypeError('events must be an array');

  const check = validate(replay(events), command);
  if (!check.ok) return check;

  const event = { type: COMMAND_TO_EVENT[command.type], at: command.at };
  if (command.type === 'open') event.owner = command.owner;
  else event.amountCents = command.amountCents;
  if (command.note !== undefined) event.note = command.note;

  return { ok: true, events: [...events, event] }; // append-only, never in place
}

/** Run a batch, keeping both the surviving log and what got refused. */
export function appendAll(events, commands) {
  let current = events;
  const rejected = [];
  for (const command of commands) {
    const result = append(current, command);
    if (result.ok) current = result.events;
    else rejected.push({ command, error: result.error });
  }
  return { events: current, rejected };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { append, appendAll, applyEvent, emptyState, replay, validate } from './ledger.js';

const OPEN = { type: 'open', owner: 'Ada', at: '2024-03-01T08:00:00Z' };
const PAY = { type: 'deposit', amountCents: 50000, at: '2024-03-01T09:00:00Z' };
const COFFEE = { type: 'withdraw', amountCents: 1250, at: '2024-03-02T08:15:00Z' };

/** Build a log, refusing to continue if the fixture itself is invalid. */
function log(...commands) {
  const { events, rejected } = appendAll([], commands);
  assert.deepEqual(rejected, [], 'fixture commands must all be valid');
  return events;
}

test('replay is deterministic: the same log always gives the same state', () => {
  const events = log(OPEN, PAY, COFFEE);
  assert.deepEqual(replay(events), replay(events));
  assert.deepEqual(replay(events), {
    open: true,
    owner: 'Ada',
    balanceCents: 48750,
    eventCount: 3,
    openedAt: '2024-03-01T08:00:00Z',
    lastEventAt: '2024-03-02T08:15:00Z',
  });
});

test('replay never mutates the log (the facts are frozen)', () => {
  const events = log(OPEN, PAY, COFFEE).map((event) => Object.freeze(event));
  Object.freeze(events);
  const before = structuredClone(events);
  replay(events);
  replay(events); // twice, to catch "the second run sees the first run's damage"
  assert.deepEqual(events, before);
});

test('order is part of the meaning: the same events, shuffled, differ', () => {
  const events = log(OPEN, PAY, COFFEE);
  const shuffled = [events[0], events[2], events[1]];
  assert.equal(replay(events).lastEventAt, '2024-03-02T08:15:00Z');
  assert.equal(replay(shuffled).lastEventAt, '2024-03-01T09:00:00Z');
  assert.equal(replay(events).balanceCents, replay(shuffled).balanceCents); // sums agree...
  assert.notDeepEqual(replay(events), replay(shuffled)); // ...but the state does not
});

test('events are plain JSON — a log survives a round trip to disk', () => {
  const events = log(OPEN, PAY, COFFEE);
  assert.deepEqual(replay(JSON.parse(JSON.stringify(events))), replay(events));
});

test('append returns a NEW log and leaves the old one alone', () => {
  const before = log(OPEN, PAY);
  const result = append(before, COFFEE);
  assert.equal(result.ok, true);
  assert.equal(before.length, 2, 'the previous log is untouched');
  assert.equal(result.events.length, 3);
  assert.notEqual(result.events, before);
});

test('a rejected command does NOT append — the log stays clean', () => {
  const before = log(OPEN, PAY);
  const bad = [
    [{ type: 'deposit', amountCents: -5000, at: '2024-03-02T00:00:00Z' }, 'INVALID_AMOUNT'],
    [{ type: 'deposit', amountCents: 0, at: '2024-03-02T00:00:00Z' }, 'INVALID_AMOUNT'],
    [{ type: 'deposit', amountCents: 12.5, at: '2024-03-02T00:00:00Z' }, 'INVALID_AMOUNT'],
    [{ type: 'withdraw', amountCents: 99999, at: '2024-03-02T00:00:00Z' }, 'INSUFFICIENT_FUNDS'],
    [{ type: 'open', owner: 'Bob', at: '2024-03-02T00:00:00Z' }, 'ALREADY_OPEN'],
    [{ type: 'deposit', amountCents: 100, at: '2020-01-01T00:00:00Z' }, 'OUT_OF_ORDER'],
    [{ type: 'deposit', amountCents: 100, at: 'last tuesday' }, 'INVALID_TIMESTAMP'],
    [{ type: 'teleport', amountCents: 100, at: '2024-03-02T00:00:00Z' }, 'UNKNOWN_COMMAND'],
    [undefined, 'UNKNOWN_COMMAND'],
  ];
  for (const [command, code] of bad) {
    const result = append(before, command);
    assert.equal(result.ok, false, `${code} should have been rejected`);
    assert.equal(result.error.code, code);
    assert.ok(result.error.message.length > 0);
    assert.equal(result.events, undefined, 'a rejection carries no log');
  }
  assert.equal(before.length, 2, 'nine rejections, zero events appended');
  assert.equal(replay(before).balanceCents, 50000);
});

test('THE original bug: the overdraft rule covers fees, not just withdrawals', () => {
  const events = log(OPEN, { type: 'deposit', amountCents: 1000, at: '2024-03-01T09:00:00Z' });
  // In original.js, chargeFee and payBill each forgot to copy the check.
  const fee = append(events, { type: 'charge-fee', amountCents: 5000, at: '2024-03-02T00:00:00Z' });
  assert.equal(fee.ok, false);
